// Builds a rotated truck marker icon for live-tracking positions — a plain <Marker icon="..."/>
// URL can't rotate a PNG, but wrapping it in an inline SVG <image> with a rotate() transform
// can. headingDeg comes from the GPS device's course/bearing field (a string in the vendor payload, e.g. "75" —
// Number.isFinite doesn't coerce strings, so it's coerced with Number() first or it'd always
// fall back to 0). Defaults to 0 (pointing up/north) when unknown rather than skipping
// rotation entirely.
//
// The truck PNG is embedded directly as a base64 data: URI inside the SVG (not referenced by a
// file path, even an absolute one) — Google Maps loads marker icons through its own internal
// image-loading path rather than a normal same-document <img> tag, and in practice a SEPARATE
// external image referenced from inside an already-data-URI SVG icon silently fails to load
// there (no request ever shows up in devtools), regardless of whether the path is relative or
// absolute. Inlining the bytes removes the external reference entirely, so there's nothing left
// that can fail to resolve.
const TRUCK_PNG_BASE64 =
  "";

export const buildTruckIcon = (headingDeg) => {
  const numericHeading = Number(headingDeg);
  const angle = Number.isFinite(numericHeading) ? numericHeading : 0;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 40 40">` +
    `<g transform="rotate(${angle} 20 20)"><image href="data:image/png;base64,${TRUCK_PNG_BASE64}" x="4" y="4" width="32" height="32" /></g>` +
    `</svg>`;
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
};
